 "<span style=\"font-family:'Bebas Neue', sans-serif;font-size:58px;color:#f07d1a\">28 × 15 m</span>&nbsp; <span style=\"font-family:'Caveat', cursive;font-size:34px\">la pista entera</span>": "<span style=\"font-family:'Bebas Neue', sans-serif;font-size:58px;color:#f07d1a\">28 × 15 m</span>&nbsp; <span style=\"font-family:'Caveat', cursive;font-size:34px\">the whole court</span>",
